// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor, uint256 t, uint256 nowOffset) public {
        amount = bound(amount, 1, 100 ether);
        vm.assume(actor != address(0));
        vm.warp(1_000_000);
        nowOffset = bound(nowOffset, 1, 10_000_000);
        uint256 target = 1_000_000 + nowOffset; // always in the future relative to warp
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(target);
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime == target);
    }
}
